function Invoke-BaselineHdc {
    param([string[]]$HdcArgs)
    $commandLine = 'hdc -t 127.0.0.1:11235 ' + ($HdcArgs -join ' ')
    $started = Get-Date -Format o
    $output = & hdc -t 127.0.0.1:11235 @HdcArgs 2>&1
    $code = $LASTEXITCODE
    @("[$started] $commandLine", $output, "EXIT=$code", '') | Add-Content -LiteralPath 'D:/HCUP/vg-spec1/traces/baseline-round-01/device-commands.log' -Encoding utf8
    $output | Write-Output
    return
}

function Save-BaselineScreen {
    param([string]$Name)
    Invoke-BaselineHdc -HdcArgs @('shell','uitest','dumpLayout','-p',"/data/local/tmp/vgspec1-$Name.json")
    Invoke-BaselineHdc -HdcArgs @('file','recv',"/data/local/tmp/vgspec1-$Name.json",".\traces\baseline-round-01\$Name.json")
    Invoke-BaselineHdc -HdcArgs @('shell','uitest','screenCap','-p',"/data/local/tmp/vgspec1-$Name.png")
    Invoke-BaselineHdc -HdcArgs @('file','recv',"/data/local/tmp/vgspec1-$Name.png",".\traces\baseline-round-01\$Name.png")
}

function Show-BaselineTexts {
    param([string]$Name)
    $tree = Get-Content -LiteralPath "D:/HCUP/vg-spec1/traces/baseline-round-01/$Name.json" -Raw | ConvertFrom-Json
    function Visit-Node {
        param($Node)
        if ($Node.attributes.text -or $Node.attributes.clickable -eq 'true') {
            $Node.attributes | Select-Object text,type,bounds,clickable,enabled,id | ConvertTo-Json -Compress
        }
        foreach ($child in $Node.children) { Visit-Node $child }
    }
    Visit-Node $tree
}

